try:
 import storage
 ro = storage.getmount('/').readonly
except Exception:
 ro = False
if not ro:
 print('rw')
else:
 try:
  storage.remount('/', False)
  print('remounted')
 except Exception as e:
  print('usb', e)

try:
 f=open('code.py','rb')
except OSError:
 print('__MISSING__')
else:
 while True:
  b=f.read(512)
  if not b: break
  print(''.join('%02x'%c for c in b), end='')
 f.close()

